  'Focus terminal': { 'af-ZA': 'Fokus terminaal', 'bg-BG': 'Фокусирай терминала', 'cs-CZ': 'Zaměřit terminál', 'da-DK': 'Fokusér terminal', 'de-DE': 'Terminal fokussieren', 'es-ES': 'Enfocar terminal', 'fr-FR': 'Focus sur le terminal', 'hr-HR': 'Fokusiraj terminal', 'id-ID': 'Fokus terminal', 'it-IT': 'Mettere a fuoco il terminale', 'ja-JP': 'ターミナルにフォーカス', 'ko-KR': '터미널에 포커스', 'pl-PL': 'Ustaw fokus na terminalu', 'pt-BR': 'Focar no terminal', 'pt-PT': 'Focar no terminal', 'ru-RU': 'Фокус на терминале', 'sr-Latn': 'Fokusiraj terminal', 'sv-SE': 'Fokusera terminal', 'tr-TR': 'Terminale odaklan', 'uk-UA': 'Фокус на терміналі', 'zh-TW': '聚焦終端' },
